<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $r=false;$error="";if($_SERVER['REQUEST_METHOD']=='POST'){$name=trim($_POST['name']??'');if($name==''||strlen($name)>60)$error="Name is required and must be less than 60 characters.";else{$name=mysqli_real_escape_string($conn,$name);$r=mysqli_query($conn,"SELECT id,name,email,city,salary FROM customers WHERE name LIKE '%$name%' ORDER BY name");}} ?>
<h2>Search Customer By Name</h2><form method="POST" class="row g-2 my-3"><div class="col-sm-6"><input type="text" name="name" maxlength="60" class="form-control" placeholder="Enter customer name" required></div><div class="col-sm-3"><button class="btn btn-primary">Search</button></div></form><?php if($error): ?><div class="alert alert-warning"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><?php if($r): ?><div class="table-responsive"><table class="table table-bordered table-striped bg-white"><thead class="table-dark"><tr><th>ID</th><th>Name</th><th>Email</th><th>City</th><th>Salary</th></tr></thead><tbody><?php if(mysqli_num_rows($r)>0): while($x=mysqli_fetch_assoc($r)): ?><tr><td><?php echo $x['id']; ?></td><td><?php echo htmlspecialchars($x['name']); ?></td><td><?php echo htmlspecialchars($x['email']); ?></td><td><?php echo htmlspecialchars($x['city']); ?></td><td><?php echo number_format($x['salary'],2); ?></td></tr><?php endwhile; else: ?><tr><td colspan="5">No customers found.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?><a href="../index.php" class="btn btn-secondary">Back Home</a><?php include "../includes/footer.php"; ?>